//! Differential tests: the Rust math must match the original Solidity libraries exactly.
//!
//! Vectors are generated by `diff-tests/` (Foundry) from the windv3swap Solidity code:
//! `cd diff-tests && forge test --match-test testGenerate`

use std::fs;
use std::path::PathBuf;

use windswap_engine::math::{
    bit_math, full_math, liquidity_math, sqrt_price_math, swap_math, tick_math, unsafe_math,
};
use windswap_engine::{MathError, I256, U256};

fn vectors(name: &str) -> Vec<(Vec<String>, Option<Vec<String>>)> {
    let path = PathBuf::from(env!("CARGO_MANIFEST_DIR"))
        .join("../../diff-tests/vectors")
        .join(format!("{name}.txt"));
    let text = fs::read_to_string(&path).unwrap_or_else(|e| panic!("read {}: {e}", path.display()));
    let cases: Vec<_> = text
        .lines()
        .filter(|l| !l.is_empty())
        .map(|line| {
            let parts: Vec<String> = line.split('|').map(str::to_owned).collect();
            if let Some(pos) = parts.iter().position(|p| p == "ok") {
                (parts[..pos].to_vec(), Some(parts[pos + 1..].to_vec()))
            } else {
                assert_eq!(
                    parts.last().map(String::as_str),
                    Some("err"),
                    "bad line: {line}"
                );
                (parts[..parts.len() - 1].to_vec(), None)
            }
        })
        .collect();
    assert!(!cases.is_empty(), "no vectors in {name}");
    cases
}

fn u(s: &str) -> U256 {
    s.parse().unwrap()
}
fn i(s: &str) -> I256 {
    I256::from_dec_str(s).unwrap()
}
fn flag(s: &str) -> bool {
    s == "1"
}

/// Compares one case: `Ok` must equal the Solidity output, `Err` must match a Solidity revert.
fn check<T: PartialEq + std::fmt::Debug>(
    name: &str,
    inputs: &[String],
    expected: &Option<Vec<String>>,
    actual: Result<T, MathError>,
    parse: impl Fn(&[String]) -> T,
) {
    match (expected, actual) {
        (Some(out), Ok(got)) => assert_eq!(got, parse(out), "{name} {inputs:?}"),
        (None, Err(_)) => {}
        (Some(out), Err(e)) => {
            panic!("{name} {inputs:?}: Solidity returned {out:?}, Rust errored {e:?}")
        }
        (None, Ok(got)) => panic!("{name} {inputs:?}: Solidity reverted, Rust returned {got:?}"),
    }
}

#[test]
fn mul_div() {
    for (inp, exp) in vectors("mul_div") {
        let r = full_math::mul_div(u(&inp[0]), u(&inp[1]), u(&inp[2]));
        check("mul_div", &inp, &exp, r, |o| u(&o[0]));
    }
}

#[test]
fn mul_div_rounding_up() {
    for (inp, exp) in vectors("mul_div_rounding_up") {
        let r = full_math::mul_div_rounding_up(u(&inp[0]), u(&inp[1]), u(&inp[2]));
        check("mul_div_rounding_up", &inp, &exp, r, |o| u(&o[0]));
    }
}

#[test]
fn div_rounding_up() {
    for (inp, exp) in vectors("div_rounding_up") {
        let r = Ok(unsafe_math::div_rounding_up(u(&inp[0]), u(&inp[1])));
        check("div_rounding_up", &inp, &exp, r, |o| u(&o[0]));
    }
}

#[test]
fn bit_math() {
    for (inp, exp) in vectors("msb") {
        check(
            "msb",
            &inp,
            &exp,
            bit_math::most_significant_bit(u(&inp[0])),
            |o| o[0].parse().unwrap(),
        );
    }
    for (inp, exp) in vectors("lsb") {
        check(
            "lsb",
            &inp,
            &exp,
            bit_math::least_significant_bit(u(&inp[0])),
            |o| o[0].parse().unwrap(),
        );
    }
}

#[test]
fn add_delta() {
    for (inp, exp) in vectors("add_delta") {
        let r = liquidity_math::add_delta(inp[0].parse().unwrap(), inp[1].parse().unwrap());
        check("add_delta", &inp, &exp, r, |o| o[0].parse().unwrap());
    }
}

#[test]
fn tick_math() {
    for (inp, exp) in vectors("sqrt_ratio_at_tick") {
        let r = tick_math::get_sqrt_ratio_at_tick(inp[0].parse().unwrap());
        check("sqrt_ratio_at_tick", &inp, &exp, r, |o| u(&o[0]));
    }
    for (inp, exp) in vectors("tick_at_sqrt_ratio") {
        let r = tick_math::get_tick_at_sqrt_ratio(u(&inp[0]));
        check("tick_at_sqrt_ratio", &inp, &exp, r, |o| {
            o[0].parse().unwrap()
        });
    }
}

#[test]
fn next_sqrt_price() {
    for (inp, exp) in vectors("next_sqrt_price_from_input") {
        let r = sqrt_price_math::get_next_sqrt_price_from_input(
            u(&inp[0]),
            inp[1].parse().unwrap(),
            u(&inp[2]),
            flag(&inp[3]),
        );
        check("next_sqrt_price_from_input", &inp, &exp, r, |o| u(&o[0]));
    }
    for (inp, exp) in vectors("next_sqrt_price_from_output") {
        let r = sqrt_price_math::get_next_sqrt_price_from_output(
            u(&inp[0]),
            inp[1].parse().unwrap(),
            u(&inp[2]),
            flag(&inp[3]),
        );
        check("next_sqrt_price_from_output", &inp, &exp, r, |o| u(&o[0]));
    }
}

#[test]
fn amount_deltas() {
    for (inp, exp) in vectors("amount0_delta") {
        let r = sqrt_price_math::get_amount0_delta(
            u(&inp[0]),
            u(&inp[1]),
            inp[2].parse().unwrap(),
            flag(&inp[3]),
        );
        check("amount0_delta", &inp, &exp, r, |o| u(&o[0]));
    }
    for (inp, exp) in vectors("amount1_delta") {
        let r = sqrt_price_math::get_amount1_delta(
            u(&inp[0]),
            u(&inp[1]),
            inp[2].parse().unwrap(),
            flag(&inp[3]),
        );
        check("amount1_delta", &inp, &exp, r, |o| u(&o[0]));
    }
    for (inp, exp) in vectors("amount0_delta_signed") {
        let r = sqrt_price_math::get_amount0_delta_signed(
            u(&inp[0]),
            u(&inp[1]),
            inp[2].parse().unwrap(),
        );
        check("amount0_delta_signed", &inp, &exp, r, |o| i(&o[0]));
    }
    for (inp, exp) in vectors("amount1_delta_signed") {
        let r = sqrt_price_math::get_amount1_delta_signed(
            u(&inp[0]),
            u(&inp[1]),
            inp[2].parse().unwrap(),
        );
        check("amount1_delta_signed", &inp, &exp, r, |o| i(&o[0]));
    }
}

#[test]
fn compute_swap_step() {
    for (inp, exp) in vectors("compute_swap_step") {
        let r = swap_math::compute_swap_step(
            u(&inp[0]),
            u(&inp[1]),
            inp[2].parse().unwrap(),
            i(&inp[3]),
            inp[4].parse().unwrap(),
        )
        .map(|s| {
            (
                s.sqrt_ratio_next_x96,
                s.amount_in,
                s.amount_out,
                s.fee_amount,
            )
        });
        check("compute_swap_step", &inp, &exp, r, |o| {
            (u(&o[0]), u(&o[1]), u(&o[2]), u(&o[3]))
        });
    }
}
